"""Exceptions for durable incident operations."""

from __future__ import annotations


class IncidentOpsError(Exception):
    """Base class for incident operation errors."""


class IncidentNotFound(IncidentOpsError):
    """Raised when a referenced incident does not exist."""

    def __init__(self, incident_id: str) -> None:
        super().__init__(f"incident not found: {incident_id}")
        self.incident_id = incident_id


class VersionConflict(IncidentOpsError):
    """Raised when an update carries a stale expected version."""

    def __init__(self, incident_id: str, expected: int, actual: int) -> None:
        super().__init__(
            f"version conflict for {incident_id}: expected {expected}, actual {actual}"
        )
        self.incident_id = incident_id
        self.expected = expected
        self.actual = actual


class InvalidTransition(IncidentOpsError):
    """Raised when a status transition or claim ownership check fails."""

    def __init__(self, message: str) -> None:
        super().__init__(message)


class InvalidSeverity(IncidentOpsError):
    """Raised when an unknown severity value is supplied."""

    def __init__(self, value: object) -> None:
        super().__init__(f"invalid severity: {value!r}")
        self.value = value

