"""Background escalation worker for the incident store."""

from __future__ import annotations

from .exceptions import InvalidTransition
from .sqlite_store import SQLiteIncidentStore


class EscalationWorker:
    """Claims overdue incidents and advances their escalation level."""

    def __init__(self, store: SQLiteIncidentStore, worker_id: str) -> None:
        if not worker_id:
            raise ValueError("worker_id is required")
        self.store = store
        self.worker_id = worker_id

    def run_once(self, now: float | None = None) -> bool:
        """Claim and complete a single overdue escalation.

        Returns ``True`` when an escalation was performed, ``False`` when no
        overdue incident was available.
        """
        # Clear any stale claims held by other workers first so a crashed
        # worker does not stall escalation.
        self.store.recover_expired_claims(now=now)
        incident = self.store.claim_due_escalation(self.worker_id, now=now)
        if incident is None:
            return False
        try:
            self.store.complete_escalation(incident.id, self.worker_id, now=now)
        except InvalidTransition:
            # Someone else recovered or the incident was resolved concurrently;
            # nothing more to do this cycle.
            return False
        return True

    def run_until_idle(
        self, max_incidents: int | None = None, now: float | None = None
    ) -> int:
        """Repeatedly escalate until no overdue incidents remain.

        Returns the number of escalations completed.
        """
        performed = 0
        while True:
            if max_incidents is not None and performed >= max_incidents:
                break
            if not self.run_once(now=now):
                break
            performed += 1
        return performed

