"""Business operations for the incident application.

The :class:`IncidentService` preserves the original in-memory API while also
supporting a durable :class:`~incident_ops.sqlite_store.SQLiteIncidentStore`.
When constructed with a durable store it proxies the durable operations so the
HTTP and CLI layers can share a single service object.
"""

from __future__ import annotations

import time
from collections.abc import Callable

from .exceptions import IncidentNotFound, InvalidSeverity, InvalidTransition, VersionConflict
from .memory_store import MemoryIncidentStore
from .models import AuditEvent, Incident, IncidentStatus, Severity
from .sqlite_store import SQLiteIncidentStore


class IncidentService:
    def __init__(
        self,
        store: MemoryIncidentStore | SQLiteIncidentStore | None = None,
        clock: Callable[[], float] = time.time,
    ) -> None:
        self.store = store or MemoryIncidentStore(clock=clock)
        self.clock = clock
        self._durable = isinstance(self.store, SQLiteIncidentStore)

    # -- original in-memory API ---------------------------------------------

    def create(self, title: str, severity: Severity | str) -> Incident:
        if not title.strip():
            raise ValueError("title is required")
        return self.store.create(title.strip(), severity)

    def list(self) -> list[Incident]:
        return self.store.list()

    def assign(self, incident_id: str, owner: str) -> Incident:
        incident = self._required(incident_id)
        return self.store.save(
            incident.changed(owner=owner.strip() or None, updated_at=self.clock())
        )

