:root {
  color: #172033;
  background: #eef2f7;
  font-family: Inter, ui-sans-serif, system-ui, sans-serif;
  --border: #d8e0ea;
  --accent: #3154a5;
  --p1: #c0262f;
  --p2: #d97706;
  --p3: #1f7a4d;
  --p4: #5b6b86;
  --danger: #c0262f;
}

* { box-sizing: border-box; }
body { margin: 0; min-height: 100vh; }

#incident-app {
  width: min(880px, calc(100% - 32px));
  margin: 24px auto;
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.app-header, .summary, .toolbar, .incident-list, .incident-detail, .incident-row, .timeline {
  background: #fff;
  border: 1px solid var(--border);
  border-radius: 14px;
  padding: 16px;
}

.app-header h1, .app-header p { margin: 0; }
.app-header h1 { font-size: 1.4rem; }
.eyebrow { color: var(--accent); font-weight: 700; text-transform: uppercase; letter-spacing: .08em; margin: 0 0 4px; font-size: .72rem; }

/* Summary cards */
.summary { display: flex; flex-wrap: wrap; gap: 10px; }
.summary .chip { flex: 1 1 120px; display: flex; flex-direction: column; gap: 2px; border: 1px solid var(--border); border-radius: 10px; padding: 10px 12px; background: #f7f9fc; }
.summary .chip .label { color: #5b6b86; font-size: .72rem; text-transform: uppercase; letter-spacing: .06em; }
.summary .chip .value { font-size: 1.6rem; font-weight: 800; line-height: 1.1; }
.summary .chip.total { background: #eef2ff; }
.summary .chip .pill { display: inline-grid; grid-auto-flow: column; gap: 14px; }

/* Toolbar */
.toolbar { display: flex; gap: 10px; align-items: flex-end; flex-wrap: wrap; }
.field { display: flex; flex-direction: column; gap: 4px; min-width: 0; }
.field > span { font-size: .72rem; text-transform: uppercase; letter-spacing: .06em; color: #5b6b86; }
input, select, button { box-sizing: border-box; min-height: 40px; padding: 7px 10px; font: inherit; border-radius: 8px; border: 1px solid var(--border); background: #fff; color: inherit; }
button { border: 0; color: #fff; background: var(--accent); font-weight: 700; cursor: pointer; }
button.ghost { background: #fff; color: var(--accent); border: 1px solid var(--accent); }
button:disabled { opacity: .5; cursor: not-allowed; }
button.danger { background: var(--danger); }

/* Feedback */
#feedback { min-height: 1.2rem; margin: 0; padding: 0 4px; font-weight: 600; }
#feedback.error { color: var(--danger); }
#feedback.success { color: var(--p3); }

/* Incident list */
.incident-list { display: grid; gap: 10px; }
.incident-list .empty { color: #5b6b86; padding: 18px; text-align: center; }
.incident-row { display: grid; grid-template-columns: 56px 1fr auto; align-items: center; gap: 12px; cursor: pointer; }
.incident-row:hover { border-color: var(--accent); }
.incident-row.active { border-color: var(--accent); box-shadow: 0 0 0 2px rgba(49,84,165,.18); }
.incident-row .badge { display: inline-flex; align-items: center; justify-content: center; height: 44px; border-radius: 10px; color: #fff; font-weight: 800; font-size: .9rem; }
.badge.P1 { background: var(--p1); }
.badge.P2 { background: var(--p2); }
.badge.P3 { background: var(--p3); }
.badge.P4 { background: var(--p4); }
.incident-row .info { min-width: 0; }
.incident-row h2, .incident-row p { margin: 0; }
.incident-row h2 { font-size: 1rem; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.incident-row .meta { color: #5b6b86; font-size: .82rem; display: flex; gap: 10px; flex-wrap: wrap; margin-top: 2px; }
.status-tag { font-weight: 700; text-transform: capitalize; }
.status-tag.open { color: var(--danger); }
.status-tag.acknowledged { color: var(--accent); }
.status-tag.resolved { color: var(--p3); }
.overdue { color: var(--danger); font-weight: 700; }
.incident-row .esc { text-align: right; font-size: .82rem; color: #5b6b86; }

/* Detail */
.incident-detail { display: flex; flex-direction: column; gap: 14px; }
.detail-head { display: flex; justify-content: space-between; gap: 10px; align-items: flex-start; flex-wrap: wrap; }
.detail-head h2 { margin: 0; font-size: 1.15rem; }
.detail-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 8px 16px; }
.detail-grid dt { color: #5b6b86; font-size: .72rem; text-transform: uppercase; letter-spacing: .06em; }
.detail-grid dd { margin: 0 0 8px; font-weight: 600; }

.controls { display: flex; gap: 10px; flex-wrap: wrap; align-items: flex-end; }
.controls .field { flex: 1 1 160px; }
.controls .actions { display: flex; gap: 8px; }

/* Timeline */
.timeline { display: flex; flex-direction: column; gap: 8px; }
.timeline h3 { margin: 0 0 4px; }
.timeline ol { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 8px; }
.timeline li { display: grid; grid-template-columns: 12px 1fr; gap: 10px; align-items: flex-start; }
.timeline li::before { content: ""; width: 10px; height: 10px; border-radius: 50%; background: var(--accent); margin-top: 6px; }
.timeline .ev-type { font-weight: 700; text-transform: capitalize; }
.timeline .ev-time { color: #5b6b86; font-size: .78rem; }
.timeline .ev-details { color: #344055; font-size: .84rem; word-break: break-word; white-space: pre-wrap; }

/* Mobile-first at 390x844 */
@media (max-width: 560px) {
  #incident-app { width: calc(100% - 16px); margin: 8px auto; gap: 10px; }
  .app-header, .summary, .toolbar, .incident-list, .incident-detail, .incident-row, .timeline { padding: 12px; border-radius: 12px; }
  .incident-row { grid-template-columns: 44px 1fr; gap: 10px; }
  .incident-row .badge { height: 40px; }
  .incident-row .esc { grid-column: 1 / -1; text-align: left; }
  .detail-grid { grid-template-columns: 1fr; }
  .summary .chip { flex: 1 1 calc(50% - 5px); }
}

