(function () {
  const listEl = document.getElementById("incident-list");
  const feedbackEl = document.getElementById("feedback");
  const summaryEl = document.getElementById("summary");
  const detailEl = document.getElementById("incident-detail");
  const statusFilterEl = document.getElementById("status-filter");
  const severityFilterEl = document.getElementById("severity-filter");
  const escalateBtn = document.getElementById("escalate-action");
  const refreshBtn = document.getElementById("refresh-action");

  const state = {
    incidents: [],
    selectedId: null,
    detail: null,
    status: "",
    severity: "",
    feedback: "",
  };

  function setFeedback(message, kind) {
    state.feedback = message || "";
    feedbackEl.textContent = state.feedback;
    feedbackEl.classList.remove("error", "success");
    if (kind) feedbackEl.classList.add(kind);
  }

  function filterQuery() {
    const params = new URLSearchParams();
    if (state.status) params.set("status", state.status);
    if (state.severity) params.set("severity", state.severity);
    const s = params.toString();
    return s ? "?" + s : "";
  }

  async function fetchJSON(url, options) {
    const response = await fetch(url, options);
    let data = null;
    const text = await response.text();
    if (text) {
      try { data = JSON.parse(text); } catch { data = text; }
    }
    return { ok: response.ok, status: response.status, data };
  }

  async function refresh() {
    const { ok, data } = await fetchJSON("/api/incidents" + filterQuery());
    if (!ok) {
      setFeedback("Could not load incidents", "error");
      state.incidents = [];
    } else {
      state.incidents = Array.isArray(data) ? data : [];
    }
    renderSummary();
    renderList();
    if (state.selectedId) {
      await selectIncident(state.selectedId, true);
    } else {
      detailEl.hidden = true;
    }
    return state.incidents;
  }

  async function loadSummary() {
    const { ok, data } = await fetchJSON("/api/summary");
    renderSummary(ok ? data : null);
    return ok ? data : null;
  }

  function renderSummary(summary) {
    summary = summary || { total: state.incidents.length, by_status: {}, by_severity: {} };
    if (summary.by_status === undefined) {
      const byStatus = {};
      const bySev = {};
      for (const inc of state.incidents) {
        byStatus[inc.status] = (byStatus[inc.status] || 0) + 1;
        bySev[inc.severity] = (bySev[inc.severity] || 0) + 1;
      }
      summary = { total: state.incidents.length, by_status: byStatus, by_severity: bySev };
    }
    const statuses = ["open", "acknowledged", "resolved"];
    const severities = ["P1", "P2", "P3", "P4"];
    summaryEl.innerHTML = "";
    const total = chip("Total", summary.total || 0, "total");
    summaryEl.appendChild(total);
    for (const s of statuses) {
      summaryEl.appendChild(chip(labelStatus(s), summary.by_status ? (summary.by_status[s] || 0) : 0, "status " + s));
    }
    for (const s of severities) {
      summaryEl.appendChild(chip(s, summary.by_severity ? (summary.by_severity[s] || 0) : 0, "sev " + s));
    }
  }

  function chip(label, value, classes) {
    const el = document.createElement("div");
    el.className = "chip " + (classes || "");
    el.innerHTML = `<span class="label"></span><span class="value"></span>`;
    el.querySelector(".label").textContent = label;
    el.querySelector(".value").textContent = String(value);
    return el;
  }

  function labelStatus(s) {
    return s.charAt(0).toUpperCase() + s.slice(1);
  }

  function renderList() {
    listEl.innerHTML = "";
    if (!state.incidents.length) {
      const empty = document.createElement("div");
      empty.className = "empty";
      empty.textContent = "No incidents match the current filters.";
      listEl.appendChild(empty);
      return;
    }
    const now = Date.now() / 1000;
    for (const inc of state.incidents) {
      listEl.appendChild(renderRow(inc, now));
    }
  }

  function renderRow(inc, now) {
    const row = document.createElement("article");
    row.setAttribute("data-testid", "incident-row");
    row.className = "incident-row " + (state.selectedId === inc.id ? "active" : "");
    row.dataset.id = inc.id;
    const overdue = inc.status !== "resolved" && inc.sla_deadline && inc.sla_deadline <= now;
    row.innerHTML = `
      <span class="badge ${inc.severity}">${inc.severity}</span>
      <div class="info">
        <h2></h2>
        <p class="meta">
          <span class="status-tag ${inc.status}">${inc.status}</span>
          <span>${inc.owner ? "Owner: " + escapeHtml(inc.owner) : "Unassigned"}</span>
          <span>v${inc.version}</span>
          <span>${overdue ? "OVERDUE" : "alerts " + inc.alert_count}</span>
        </p>
      </div>
      <div class="esc">esc ${inc.escalation_level}</div>`;
    row.querySelector("h2").textContent = inc.title;
    row.addEventListener("click", () => selectIncident(inc.id));
    return row;
  }

  async function selectIncident(id, silent) {
    state.selectedId = id;
    renderList();
    const { ok, status, data } = await fetchJSON("/api/incidents/" + encodeURIComponent(id));
    if (!ok) {
      if (status === 404) {
