(function () {
  const listEl = document.getElementById("incident-list");
  const feedbackEl = document.getElementById("feedback");
  const summaryEl = document.getElementById("summary");
  const detailEl = document.getElementById("incident-detail");
  const statusFilterEl = document.getElementById("status-filter");
  const severityFilterEl = document.getElementById("severity-filter");
  const escalateBtn = document.getElementById("escalate-action");
  const refreshBtn = document.getElementById("refresh-action");

  const state = {
    incidents: [],
    selectedId: null,
    detail: null,
    status: "",
    severity: "",
    feedback: "",
  };

  function setFeedback(message, kind) {
    state.feedback = message || "";
    feedbackEl.textContent = state.feedback;
    feedbackEl.classList.remove("error", "success");
    if (kind) feedbackEl.classList.add(kind);
  }

  function filterQuery() {
    const params = new URLSearchParams();
    if (state.status) params.set("status", state.status);
    if (state.severity) params.set("severity", state.severity);
    const s = params.toString();
    return s ? "?" + s : "";
  }

  async function fetchJSON(url, options) {
    const response = await fetch(url, options);
    let data = null;
    const text = await response.text();
    if (text) {
      try { data = JSON.parse(text); } catch { data = text; }
    }
    return { ok: response.ok, status: response.status, data };
  }

  async function refresh() {
    const { ok, data } = await fetchJSON("/api/incidents" + filterQuery());
    if (!ok) {
      setFeedback("Could not load incidents", "error");
      state.incidents = [];
    } else {
      state.incidents = Array.isArray(data) ? data : [];
    }
    renderSummary();
    renderList();
    if (state.selectedId) {
      await selectIncident(state.selectedId, true);
    } else {
      detailEl.hidden = true;
    }
    return state.incidents;
  }

  async function loadSummary() {
    const { ok, data } = await fetchJSON("/api/summary");
    renderSummary(ok ? data : null);
    return ok ? data : null;
  }

  function renderSummary(summary) {
    summary = summary || { total: state.incidents.length, by_status: {}, by_severity: {} };
    if (summary.by_status === undefined) {
      const byStatus = {};
      const bySev = {};
      for (const inc of state.incidents) {
        byStatus[inc.status] = (byStatus[inc.status] || 0) + 1;
        bySev[inc.severity] = (bySev[inc.severity] || 0) + 1;
      }
      summary = { total: state.incidents.length, by_status: byStatus, by_severity: bySev };
    }
    const statuses = ["open", "acknowledged", "resolved"];
    const severities = ["P1", "P2", "P3", "P4"];
    summaryEl.innerHTML = "";
    const total = chip("Total", summary.total || 0, "total");
    summaryEl.appendChild(total);
    for (const s of statuses) {
      summaryEl.appendChild(chip(labelStatus(s), summary.by_status ? (summary.by_status[s] || 0) : 0, "status " + s));
    }
    for (const s of severities) {
      summaryEl.appendChild(chip(s, summary.by_severity ? (summary.by_severity[s] || 0) : 0, "sev " + s));
    }
  }

  function chip(label, value, classes) {
    const el = document.createElement("div");
    el.className = "chip " + (classes || "");
    el.innerHTML = `<span class="label"></span><span class="value"></span>`;
    el.querySelector(".label").textContent = label;
    el.querySelector(".value").textContent = String(value);
    return el;
  }

  function labelStatus(s) {
    return s.charAt(0).toUpperCase() + s.slice(1);
  }

  function renderList() {
    listEl.innerHTML = "";
    if (!state.incidents.length) {
      const empty = document.createElement("div");
      empty.className = "empty";
      empty.textContent = "No incidents match the current filters.";
      listEl.appendChild(empty);
      return;
    }
    const now = Date.now() / 1000;
    for (const inc of state.incidents) {
      listEl.appendChild(renderRow(inc, now));
    }
  }

  function renderRow(inc, now) {
    const row = document.createElement("article");
    row.setAttribute("data-testid", "incident-row");
    row.className = "incident-row " + (state.selectedId === inc.id ? "active" : "");
    row.dataset.id = inc.id;
    const overdue = inc.status !== "resolved" && inc.sla_deadline && inc.sla_deadline <= now;
    row.innerHTML = `
      <span class="badge ${inc.severity}">${inc.severity}</span>
      <div class="info">
        <h2></h2>
        <p class="meta">
          <span class="status-tag ${inc.status}">${inc.status}</span>
          <span>${inc.owner ? "Owner: " + escapeHtml(inc.owner) : "Unassigned"}</span>
          <span>v${inc.version}</span>
          <span>${overdue ? "OVERDUE" : "alerts " + inc.alert_count}</span>
        </p>
      </div>
      <div class="esc">esc ${inc.escalation_level}</div>`;
    row.querySelector("h2").textContent = inc.title;
    row.addEventListener("click", () => selectIncident(inc.id));
    return row;
  }

  async function selectIncident(id, silent) {
    state.selectedId = id;
    renderList();
    const { ok, status, data } = await fetchJSON("/api/incidents/" + encodeURIComponent(id));
    if (!ok) {
      if (status === 404) {
        setFeedback("Incident " + id + " was removed", "error");
        state.selectedId = null;
        detailEl.hidden = true;
      } else {
        setFeedback("Could not load incident details", "error");
      }
      return;
    }
    state.detail = data;
    renderDetail(data);
    if (!silent) setFeedback("");
  }

  function renderDetail(inc) {
    detailEl.hidden = false;
    detailEl.innerHTML = "";
    const head = document.createElement("div");
    head.className = "detail-head";
    head.innerHTML = `<div><span class="badge ${inc.severity}">${inc.severity}</span> <h2></h2></div>`;
    head.querySelector("h2").textContent = inc.title;

    const grid = document.createElement("dl");
    grid.className = "detail-grid";
    const rows = [
      ["Status", labelStatus(inc.status)],
      ["Owner", inc.owner || "Unassigned"],
      ["Fingerprint", inc.fingerprint],
      ["Alert count", inc.alert_count],
      ["Version", inc.version],
      ["Escalation level", inc.escalation_level],
      ["Created", fmtTime(inc.created_at)],
      ["Updated", fmtTime(inc.updated_at)],
      ["SLA deadline", fmtTime(inc.sla_deadline)],
      ["ID", inc.id],
    ];
    for (const [label, value] of rows) {
      const dt = document.createElement("dt");
      dt.textContent = label;
      const dd = document.createElement("dd");
      dd.textContent = String(value);
      grid.appendChild(dt);
      grid.appendChild(dd);
    }

    const controls = document.createElement("div");
    controls.className = "controls";
    const ownerField = document.createElement("label");
    ownerField.className = "field";
    ownerField.innerHTML = `<span>Owner</span>`;
    const ownerInput = document.createElement("input");
    ownerInput.setAttribute("data-testid", "owner-input");
    ownerInput.id = "owner-input";
    ownerInput.value = inc.owner || "";
    ownerField.appendChild(ownerInput);

    const actions = document.createElement("div");
    actions.className = "actions";
    const ackBtn = document.createElement("button");
    ackBtn.setAttribute("data-testid", "acknowledge-action");
    ackBtn.textContent = "Acknowledge";
    ackBtn.addEventListener("click", () => updateIncident(inc, { status: "acknowledged" }));
    const resBtn = document.createElement("button");
    resBtn.setAttribute("data-testid", "resolve-action");
    resBtn.className = "danger";
    resBtn.textContent = "Resolve";
    resBtn.addEventListener("click", () => updateIncident(inc, { status: "resolved" }));
    const assignBtn = document.createElement("button");
    assignBtn.textContent = "Assign";
    assignBtn.addEventListener("click", () => updateIncident(inc, { owner: ownerInput.value }));
    actions.appendChild(assignBtn);
    actions.appendChild(ackBtn);
    actions.appendChild(resBtn);

    controls.appendChild(ownerField);
    controls.appendChild(actions);

    const timeline = document.createElement("section");
    timeline.setAttribute("data-testid", "timeline");
    timeline.className = "timeline";
    const heading = document.createElement("h3");
    heading.textContent = "Audit timeline";
    const ol = document.createElement("ol");
    for (const ev of inc.events || []) {
      const li = document.createElement("li");
      li.innerHTML = `<div><span class="ev-type"></span> <span class="ev-time"></span><div class="ev-details"></div></div>`;
      li.querySelector(".ev-type").textContent = ev.type.replace(/_/g, " ");
      li.querySelector(".ev-time").textContent = fmtTime(ev.timestamp);
      li.querySelector(".ev-details").textContent = ev.details ? JSON.stringify(ev.details) : "";
      ol.appendChild(li);
    }
    timeline.appendChild(heading);
    timeline.appendChild(ol);

    detailEl.appendChild(head);
    detailEl.appendChild(grid);
    detailEl.appendChild(controls);
    detailEl.appendChild(timeline);
  }

  async function updateIncident(inc, changes) {
    const body = Object.assign({ expected_version: inc.version }, changes);
    const { ok, status, data } = await fetchJSON("/api/incidents/" + encodeURIComponent(inc.id), {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(body),
    });
    if (!ok) {
      const msg = (data && data.error) ? data.error : "Update failed (HTTP " + status + ")";
      if (status === 409) {
        setFeedback("Conflict: " + msg, "error");
      } else {
        setFeedback(msg, "error");
      }
      await refresh();
      return;
    }
    setFeedback("Incident updated", "success");
    await loadSummary();
    await refresh();
  }

  async function runEscalations() {
    escalateBtn.disabled = true;
    try {
      const { ok, data } = await fetchJSON("/api/escalations/run", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ worker_id: "browser" }),
      });
      if (ok) {
        const n = data && data.escalated ? data.escalated : 0;
        setFeedback(n > 0 ? "Escalated " + n + " incident(s)" : "No overdue incidents", "success");
      } else {
        setFeedback("Escalation run failed", "error");
      }
      await loadSummary();
      await refresh();
    } finally {
      escalateBtn.disabled = false;
    }
  }

  function fmtTime(ts) {
    if (!ts) return "—";
    const d = new Date(ts * 1000);
    if (isNaN(d.getTime())) return String(ts);
    return d.toISOString().replace("T", " ").replace(/\.\d+Z$/, "Z");
  }

  function escapeHtml(s) {
    return String(s).replace(/[&<>"']/g, (c) => ({
      "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;",
    }[c]));
  }

  statusFilterEl.addEventListener("change", () => {
    state.status = statusFilterEl.value;
    refresh();
  });
  severityFilterEl.addEventListener("change", () => {
    state.severity = severityFilterEl.value;
    refresh();
  });
  escalateBtn.addEventListener("click", runEscalations);
  refreshBtn.addEventListener("click", () => { setFeedback(""); refresh(); });

  window.incidentOps = {
    refresh,
    selectIncident,
    getState: () => ({
      status: state.status,
      severity: state.severity,
      selectedId: state.selectedId,
      incidents: state.incidents,
      feedback: state.feedback,
    }),
  };

  refresh();
  loadSummary();
})();

