// Verify the Incident Ops browser interface using jsdom against the live server.
const fs = require("fs");
const path = require("path");
const { JSDOM, ResourceLoader, VirtualConsole } = require("jsdom");

const BASE = process.env.BASE_URL || "http://127.0.0.1:8199";

function fail(msg) {
  console.error("FAIL:", msg);
  process.exit(1);
}

const STATIC = path.join(
  "<local-workspace>",
  "incident_ops/static"
);

const consoleErrors = [];
const vc = new VirtualConsole();
vc.on("jsdomError", (e) => consoleErrors.push(String(e)));
vc.on("error", (...a) => consoleErrors.push(a.join(" ")));

async function main() {
  const html = fs.readFileSync(path.join(STATIC, "index.html"), "utf8");
  const css = fs.readFileSync(path.join(STATIC, "styles.css"), "utf8");
  const js = fs.readFileSync(path.join(STATIC, "app.js"), "utf8");

  // Fetch stub backed by the live server (so we exercise real JSON).
  const incidents = [
    {
      id: "inc-1", fingerprint: "fp-1", title: "Database errors", severity: "P1",
      status: "open", owner: null, alert_count: 2, version: 2, escalation_level: 0,
      created_at: 100.0, updated_at: 150.0, sla_deadline: 160.0,
      events: [
        { id: 1, incident_id: "inc-1", type: "created", timestamp: 100.0, details: {} },
        { id: 2, incident_id: "inc-1", type: "duplicate_alert", timestamp: 150.0, details: { alert_count: 2 } },
      ],
    },
    {
      id: "inc-2", fingerprint: "fp-2", title: "Network slow", severity: "P2",
      status: "acknowledged", owner: "Rajiv", alert_count: 1, version: 1, escalation_level: 0,
      created_at: 120.0, updated_at: 120.0, sla_deadline: 420.0, events: [
        { id: 3, incident_id: "inc-2", type: "created", timestamp: 120.0, details: {} },
      ],
    },
  ];

  function fakeFetch(url, options) {
    return Promise.resolve({
      ok: true,
      status: 200,
      text: () => Promise.resolve(JSON.stringify(_route(url, options))),
    });
  }

  function _route(url, options) {
    if (url.startsWith("/api/incidents/")) {
      const id = url.split("/").pop();
      return incidents.find((i) => i.id === id);
    }
    if (url.startsWith("/api/incidents")) {
      // honor filters
      const u = new URL("http://x" + url);
      const status = u.searchParams.get("status");
      const sev = u.searchParams.get("severity");
      return incidents.filter(
        (i) => (!status || i.status === status) && (!sev || i.severity === sev)
      );
    }
    if (url.startsWith("/api/summary")) {
      return { total: 2, by_status: { open: 1, acknowledged: 1 }, by_severity: { P1: 1, P2: 1 } };
    }
    if (url === "/api/escalations/run") {
      return { escalated: 1, worker_id: "browser" };
    }
    return null;
  }

  const dom = new JSDOM(html, {
    runScripts: "dangerously",
    pretendToBeVisual: true,
    virtualConsole: vc,
    url: BASE + "/",
    beforeParse(window) {
      window.fetch = fakeFetch;
      window.requestAnimationFrame = (cb) => setTimeout(cb, 0);
      window.URLSearchParams = URLSearchParams;
    },
  });
  const { window } = dom;
  // Inject CSS into a style element to validate parsing.
  const style = window.document.createElement("style");
  style.textContent = css;
  window.document.head.appendChild(style);
  // Inject app.js by evaluating it in the window context.
  try {
    const fn = new window.Function(js);
    fn.call(window);
  } catch (e) {
    fail("app.js threw on load: " + e.stack);
  }

  // Wait a tick for async refresh.
  await new Promise((r) => setTimeout(r, 50));

  const doc = window.document;
  function testid(name) {
    return doc.querySelector(`[data-testid="${name}"]`);
  }
  for (const name of [
    "incident-app", "summary", "incident-list", "incident-detail",
    "status-filter", "severity-filter", "owner-input", "acknowledge-action",
    "resolve-action", "feedback",
  ]) {
    const el = testid(name);
    if (!el) {
      // owner-input/acknowledge/resolve/timeline only exist after selecting an incident.
      if (["owner-input", "acknowledge-action", "resolve-action", "timeline"].includes(name)) {
        continue;
      }
      fail("missing data-testid=" + name);
    }
  }

  // Summary rendered with chips.
  if (!testid("summary").textContent.includes("Total")) fail("summary missing Total");
  // Incident rows.
  const rows = doc.querySelectorAll('[data-testid="incident-row"]');
  if (rows.length !== 2) fail("expected 2 rows, got " + rows.length);

  // Select first incident -> detail should appear with timeline, owner input, actions.
  await window.incidentOps.selectIncident("inc-1");
  await new Promise((r) => setTimeout(r, 20));
  for (const name of ["incident-detail", "timeline", "owner-input", "acknowledge-action", "resolve-action"]) {
    if (!testid(name)) fail("after select, missing data-testid=" + name);
  }
  const tl = testid("timeline");
  if (!tl.textContent.includes("created")) fail("timeline missing created event");

  // Contract.
  if (typeof window.incidentOps !== "object") fail("window.incidentOps missing");
  if (typeof window.incidentOps.refresh !== "function") fail("refresh missing");
  if (typeof window.incidentOps.selectIncident !== "function") fail("selectIncident missing");
  if (typeof window.incidentOps.getState !== "function") fail("getState missing");
  const st = window.incidentOps.getState();
  if (st.selectedId !== "inc-1") fail("getState selectedId wrong: " + st.selectedId);
