function _route(url, options) {
  const method = (options && options.method) || "GET";
  if (url.startsWith("/api/incidents/") && method !== "PATCH") {
    const id = url.split("/").pop();
    return incidents.find((i) => i.id === id);
  }
  if (url.startsWith("/api/incidents/") && method === "PATCH") {
    const id = url.split("/").pop();
    const body = options.body ? JSON.parse(options.body) : {};
    const inc = incidents.find((i) => i.id === id);
    if (!inc) return { error: "not found" };
    if (body.expected_version !== inc.version) {
      return { error: "conflict", expected: body.expected_version, actual: inc.version };
    }
    const updated = Object.assign({}, inc, {
      status: body.status || inc.status,
      owner: body.owner !== undefined ? (body.owner || null) : inc.owner,
      version: inc.version + 1,
      updated_at: 999.0,
    });
    Object.assign(inc, updated);
    return updated;
  }
  if (url.startsWith("/api/incidents")) {
    const u = new URL("http://x" + url);
    const status = u.searchParams.get("status");
    const sev = u.searchParams.get("severity");
    return incidents.filter(
      (i) => (!status || i.status === status) && (!sev || i.severity === sev)
    );
  }
  if (url.startsWith("/api/summary")) {
    return { total: incidents.length, by_status: { open: 1, acknowledged: 1 }, by_severity: { P1: 1, P2: 1 } };
  }
  if (url === "/api/escalations/run") {
    return { escalated: 1, worker_id: "browser" };
  }
  return null;
}

