const { chromium } = require("playwright");

const BASE = process.env.BASE_URL || "http://127.0.0.1:8199";

function fail(msg) {
  console.error("FAIL:", msg);
  process.exit(1);
}

(async () => {
  const browser = await chromium.launch({ headless: true });
  const context = await browser.newContext({ viewport: { width: 390, height: 844 } });
  const page = await context.newPage();
  const consoleErrors = [];
  page.on("console", (msg) => { if (msg.type() === "error") consoleErrors.push(msg.text()); });
  page.on("pageerror", (e) => consoleErrors.push(String(e)));

  await page.goto(BASE + "/", { waitUntil: "networkidle", timeout: 15000 });
  // Seed an incident via the API to make the list non-empty.
  await page.evaluate(async () => {
    const body = { fingerprint: "fp-1", title: "Database errors", severity: "P1" };
    await fetch("/api/alerts", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(body) });
    const body2 = { fingerprint: "fp-2", title: "Network slow", severity: "P2" };
    await fetch("/api/alerts", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(body2) });
  });

  await page.evaluate(() => window.incidentOps.refresh());
  await page.waitForTimeout(300);

  // Check markers present.
  for (const name of ["incident-app", "summary", "incident-list", "incident-row", "status-filter", "severity-filter", "feedback"]) {
    const count = await page.locator(`[data-testid="${name}"]`).count();
    if (count === 0) fail(`missing data-testid=${name}`);
  }

